VOCAB = {"hello": 101, " world": 102, "un": 201, "believ": 202, "able": 203, "!": 301}
def tokenize(text):
    out, i = [], 0
    pieces = ["hello", " world", "un", "believ", "able", "!"]
    while i < len(text):
        for p in pieces:
            if text.startswith(p, i):
                out.append((p, VOCAB[p])); i += len(p); break
        else:
            out.append((text[i], 999)); i += 1
    return out
for s in ["hello world!", "unbelievable!"]:
    toks = tokenize(s)
    print(repr(s), "->", toks, "count:", len(toks))

VOCAB = {"un": 1, "##happi": 2, "##ness": 3, "dog": 4, "##s": 5, "play": 6, "##ing": 7}
def wordpiece(word):
    if word in VOCAB: return [word]
    out, i, first = [], 0, True
    while i < len(word):
        found = None
        for j in range(len(word), i, -1):
            piece = word[i:j] if first else "##" + word[i:j]
            if piece in VOCAB:
                found = piece; break
        if found is None: return ["[UNK]"]
        out.append(found); i += len(found.lstrip("#")); first = False
    return out
for w in ["unhappiness", "dogs", "playing", "xqzt"]:
    print(w, "->", wordpiece(w))

