# Tiny unigram-style model: piece log-probs; best segmentation by Viterbi.
PIECES = {"un": -1.0, "happi": -2.0, "ness": -1.5, "unhappi": -3.0,
          "happy": -0.5, "unhappy": -0.8, "h": -4.0, "a": -4.0}
def best_seg(word):
    n = len(word)
    dp = [(-1e18, None)] * (n + 1)
    dp[0] = (0.0, [])
    for i in range(n):
        if dp[i][0] == -1e18: continue
        for j in range(i + 1, n + 1):
            p = word[i:j]
            if p in PIECES and dp[i][0] + PIECES[p] > dp[j][0]:
                dp[j] = (dp[i][0] + PIECES[p], dp[i][1] + [p])
    return dp[n]
for w in ["unhappy", "unhappiness"]:
    score, seg = best_seg(w)
    print(w, "->", seg, "log-prob:", round(score, 2) if seg else "no segmentation")

