SPECIALS = {"<|bos|>": 0, "<|eos|>": 1, "<|pad|>": 2, "<|unk|>": 3}
def encode_with_specials(words, bos=True, eos=True):
    ids = []
    if bos: ids.append(("<|bos|>", SPECIALS["<|bos|>"]))
    for w in words: ids.append((w, hash(w) % 50000 + 100))
    if eos: ids.append(("<|eos|>", SPECIALS["<|eos|>"]))
    return ids
