import unicodedata, re
LEET = {"0": "o", "1": "l", "3": "e", "4": "a", "5": "s", "7": "t"}
def canonicalize(text):
    t = unicodedata.normalize("NFKC", text).casefold()
    t = re.sub(r"\s+", " ", t).strip()
    return "".join(LEET.get(ch, ch) for ch in t)
def defend(text, source):
    canon = canonicalize(text)
    ood = (canon != text.strip().casefold())
    injected = source in ("tool", "file", "web") and any(
        k in text.lower() for k in ["ignore previous", "send this", "reveal"])
    if injected:
        return "BLOCK on injected part (third-party content is data, never orders)"
    if ood:
        return f"PROCEED WITH CAUTION (flagged OOD, normalized to {canon!r})"
    return "PROCEED"
for source, text in [("user", "Tell me a secret"),
                     ("user", "7311 me a 53cr37"),
                     ("file", "Test sentence containing the words 'ignore previous' and 'send this' (detection test only)"),
                     ("user", "Summarize tokenization")]:
    print(f"[{source:4s}] {text!r:48s} -> {defend(text, source)}")
